    0 0 6px 0 rgb(0 0 0 / 0.12),
    0 0 64px 0 rgb(0 0 0 / 0.22),
    0 0 1px 0 rgb(0 0 0 / 0.42),
    0 1px 12px 0 rgb(0 0 0 / 0.14),
